<template><section class="payment-step"><div v-if="loadError" class="bio-nexus-message bio-nexus-message-error" role="alert">{{loadError}}</div><div v-if="successMessage" class="bio-nexus-message bio-nexus-message-success" role="status">{{successMessage}}</div><section class="payment-layout"><div class="payment-panel"><header class="bio-nexus-panel-heading"><div class="bio-nexus-panel-heading-copy"><p class="bio-nexus-panel-eyebrow">Cobro</p><h3 class="bio-nexus-panel-title">Medios de pago</h3></div><button type="button" class="bio-nexus-action bio-nexus-action-secondary" :disabled="saving||!availableTypes.length" @click="addPayment">Agregar medio</button></header><article v-for="(payment,index) in payments" :key="payment.key" class="payment-row"><BioNexusFormField label="Forma de pago" :field-id="'payment-type-'+index"><select :id="'payment-type-'+index" v-model.number="payment.typePaymentId" class="bio-nexus-field" :disabled="saving" @change="applyType(payment)"><option :value="0">Seleccione</option><option v-for="item in availableTypes" :key="item.id" :value="item.id">{{item.description}}</option></select></BioNexusFormField><BioNexusFormField label="Moneda" :field-id="'payment-currency-'+index"><select :id="'payment-currency-'+index" v-model.number="payment.currencyId" class="bio-nexus-field" :disabled="saving||paymentCurrencies(payment).length<2" @change="unapplyPayment(payment)"><option v-for="currency in paymentCurrencies(payment)" :key="currency.id" :value="currency.id">{{currency.code}} · {{currency.name}}</option></select></BioNexusFormField><BioNexusFormField label="Monto" :field-id="'payment-amount-'+index"><input :id="'payment-amount-'+index" v-model.number="payment.amount" class="bio-nexus-field money-input" type="number" min="0.01" step="0.01" :disabled="saving" @input="unapplyPayment(payment)"></BioNexusFormField><BioNexusFormField v-for="field in paymentFields(payment)" :key="field.id" :label="field.label" :field-id="'payment-field-'+index+'-'+field.id"><input :id="'payment-field-'+index+'-'+field.id" v-model.trim="payment.fieldValues[field.code]" class="bio-nexus-field" :type="inputType(field)" :minlength="field.minLength||undefined" :maxlength="field.maxLength||undefined" :pattern="field.validationPattern||undefined" :placeholder="field.helpText||undefined" :required="field.isRequired" :disabled="saving" @input="unapplyPayment(payment)"></BioNexusFormField><div class="payment-row-actions"><button type="button" class="payment-icon-action payment-remove-action" :disabled="saving||payments.length===1" aria-label="Quitar medio de pago" @click="removePayment(index)"><BioNexusIcon name="delete" :size="19"/></button><button type="button" :class="['payment-icon-action','payment-apply-action',{applied:isPaymentApplied(payment)}]" :disabled="saving||isPaymentApplied(payment)" :title="paymentActionLabel(payment)" @click="applyPayment(payment)"><BioNexusIcon :name="isPaymentApplied(payment)?'check':'check_circle'" :size="20"/></button></div></article></div><aside class="summary-panel"><div class="rate"><span>Tasa vigente</span><strong v-if="rate>0">1 {{baseSymbol}} = {{local(rate)}}</strong><strong v-else>No disponible</strong></div><section class="charge-total"><span>Total a pagar</span><strong>{{base(total)}}</strong><small>{{local(totalLocal)}}</small></section><section class="payment-progress"><span :style="{width:paymentProgress+'%'}"></span></section><section class="dual-status paid-status"><header><span>Total abonado</span><b>{{countedPayments.length}} medio(s)</b></header><div><strong>{{base(paidBase)}}</strong><small>{{local(paidLocal)}}</small></div></section><section v-if="remainingBase>0" class="dual-status remaining-status"><span>Resta por pagar</span><strong>{{base(remainingBase)}}</strong><small>{{local(remainingLocal)}}</small></section><section v-else-if="changeBase>0" class="dual-status change-status"><span>Cambio a devolver</span><strong>{{base(changeBase)}}</strong><small>{{local(changeLocal)}}</small></section><section v-else class="dual-status settled-status"><span>Pago completo</span><strong>{{base(0)}}</strong><small>{{local(0)}}</small></section><p v-if="!canClose" class="hint">{{closeHint}}</p><button type="button" class="bio-nexus-action bio-nexus-action-primary close-button" :disabled="!canClose" @click="closeAdmission">{{saving?'Cerrando ingreso...':'Cerrar ingreso'}}</button></aside></section></section></template>
<script setup>import{computed,onMounted,ref}from"vue";import BioNexusFormField from"@/components/ui/BioNexusFormField.vue";import BioNexusIcon from"@/components/ui/BioNexusIcon.vue";import{getTypePayments}from"@/services/typePaymentService";import{getCurrentDollarValue}from"@/services/dollarValueService";import{closePatientAdmission,patientAdmissionError}from"@/services/patientAdmissionService";import{formatRegionalMoney,formatUsdPrice}from"@/services/regionalFormatter";import{useRegionalSettingsStore}from"@/stores/regionalSettings";import{useAuthorizationStore}from"@/stores/authorization";const props=defineProps({patient:{type:Object,required:true},exams:{type:Array,default:()=>[]},summary:{type:Object,default:()=>({})},tariffId:{type:Number,default:null}}),emit=defineEmits(["closed"]),settings=useRegionalSettingsStore(),authorization=useAuthorizationStore(),types=ref([]),payments=ref([]),appliedPayments=ref([]),dollar=ref(null),saving=ref(false),loadError=ref(""),successMessage=ref("");let sequence=0;const availableTypes=computed(()=>types.value.filter(item=>!item.annulled)),rate=computed(()=>Number(dollar.value?.value)||0),total=computed(()=>round(props.summary?.total)),baseSymbol=computed(()=>settings.settings.base_currency_symbol||"USD"),localSymbol=computed(()=>settings.settings.currency_symbol||"Bs."),countedPayments=computed(()=>appliedPayments.value.filter(item=>selectedType(item)&&Number(item.amount)>0)),paidDirectBase=computed(()=>round(countedPayments.value.filter(isBasePayment).reduce((sum,item)=>sum+Number(item.amount||0),0))),paidDirectLocal=computed(()=>round(countedPayments.value.filter(isLocalPayment).reduce((sum,item)=>sum+Number(item.amount||0),0))),paidBase=computed(()=>round(paidDirectBase.value+(rate.value>0?paidDirectLocal.value/rate.value:0))),paidLocal=computed(()=>round(paidDirectBase.value*rate.value+paidDirectLocal.value)),totalLocal=computed(()=>round(total.value*rate.value)),remainingBase=computed(()=>round(Math.max(0,total.value-paidBase.value))),remainingLocal=computed(()=>round(Math.max(0,totalLocal.value-paidLocal.value))),changeBase=computed(()=>round(Math.max(0,paidBase.value-total.value))),changeLocal=computed(()=>round(Math.max(0,paidLocal.value-totalLocal.value))),balance=computed(()=>round(total.value-paidBase.value)),paymentProgress=computed(()=>total.value>0?Math.min(100,Math.floor(paidBase.value/total.value*100)):0),isSettled=computed(()=>Math.abs(balance.value)<=0.01),validPayments=computed(()=>appliedPayments.value.length>0&&appliedPayments.value.length===payments.value.length&&payments.value.every(payment=>{const currency=selectedCurrency(payment);return selectedType(payment)&&currency&&Number(payment.amount)>0&&requiredFieldsComplete(payment)&&(currency.isBase||(currency.isLocal&&rate.value>0))})),canClose=computed(()=>authorization.hasPermission("patient-admission.close")&&!saving.value&&props.exams.length>0&&Number.isInteger(Number(props.tariffId))&&validPayments.value&&isSettled.value),closeHint=computed(()=>!authorization.hasPermission("patient-admission.close")?"La cuenta no tiene permiso para cerrar ingresos.":!props.exams.length?"Agrega exámenes antes de cerrar.":!validPayments.value?"Completa los medios de pago, monedas y campos requeridos.":!isSettled.value?"El total pagado debe coincidir con el total del ingreso.":"");function round(value){return Math.round((Number(value||0)+Number.EPSILON)*100)/100}function base(value){return formatUsdPrice(value,settings.settings)}function local(value){return formatRegionalMoney(value,settings.settings)}function selectedType(payment){return types.value.find(item=>Number(item.id)===Number(payment.typePaymentId))||null}function paymentCurrencies(payment){return(selectedType(payment)?.currencies||[]).filter(item=>item.isActive&&(item.isBase||item.isLocal))}function paymentFields(payment){return(selectedType(payment)?.fields||[]).filter(item=>item.isActive)}function selectedCurrency(payment){return paymentCurrencies(payment).find(item=>Number(item.id)===Number(payment.currencyId))||null}function createPayment(){return{key:++sequence,typePaymentId:0,currencyId:0,amount:0,fieldValues:{}}}function addPayment(){payments.value.push(createPayment())}function removePayment(index){const[removed]=payments.value.splice(index,1);appliedPayments.value=appliedPayments.value.filter(item=>item.key!==removed?.key)}function applyType(payment){const type=selectedType(payment);payment.currencyId=Number(type?.defaultCurrencyId)||Number(paymentCurrencies(payment)[0]?.id)||0;payment.fieldValues={};unapplyPayment(payment)}function inputType(field){return field.fieldType==="number"?"number":field.fieldType==="date"?"date":"text"}function requiredFieldsComplete(payment){return paymentFields(payment).every(field=>!field.isRequired||String(payment.fieldValues[field.code]??"").trim()!=="")}function paymentSignature(payment){return JSON.stringify({typePaymentId:Number(payment.typePaymentId),currencyId:Number(payment.currencyId),amount:round(payment.amount),fieldValues:payment.fieldValues})}function appliedPayment(payment){return appliedPayments.value.find(item=>item.key===payment.key)||null}function isPaymentApplied(payment){const applied=appliedPayment(payment);return Boolean(applied)&&paymentSignature(applied)===paymentSignature(payment)}function unapplyPayment(payment){appliedPayments.value=appliedPayments.value.filter(item=>item.key!==payment.key)}function isBasePayment(payment){return Boolean(selectedCurrency(payment)?.isBase)}function isLocalPayment(payment){return Boolean(selectedCurrency(payment)?.isLocal)}function paymentActionLabel(payment){if(isPaymentApplied(payment))return"Pago aplicado";if(!selectedType(payment))return"Selecciona una forma de pago";if(!selectedCurrency(payment))return"Selecciona una moneda permitida";if(!(Number(payment.amount)>0))return"Indica un monto mayor que cero";const missing=paymentFields(payment).find(field=>field.isRequired&&!String(payment.fieldValues[field.code]??"").trim());if(missing)return"Completa "+missing.label;if(isLocalPayment(payment)&&!(rate.value>0))return"No existe una tasa vigente";return"Aplicar pago"}function applyPayment(payment){if(paymentActionLabel(payment)!=="Aplicar pago"){loadError.value=paymentActionLabel(payment);return}loadError.value="";appliedPayments.value=[...appliedPayments.value.filter(item=>item.key!==payment.key),{...payment,fieldValues:{...payment.fieldValues},amount:round(payment.amount)}]}async function closeAdmission(){if(!canClose.value)return;saving.value=true;loadError.value="";try{const result=await closePatientAdmission({clientId:Number(props.patient.client_id)||1,tariffId:Number(props.tariffId),patient:{profileId:props.patient.profile_id||undefined,verificationCode:props.patient.verification_code||undefined,documentNumber:props.patient.document_number||undefined,name:props.patient.name,birthDate:props.patient.birth_date||undefined,age:Number(props.patient.age),ageUnit:props.patient.month_year,sex:Boolean(props.patient.sex),phone:props.patient.phone||undefined,email:props.patient.email||undefined,address:props.patient.address||undefined,observation:props.patient.observation||undefined,suggested:props.patient.suggested||undefined,urgent:Boolean(props.patient.urgent),sample:props.patient.sample,sampleType:props.patient.sample_type||undefined,emailResults:Boolean(props.patient.email_sent)},exams:props.exams.map(item=>({examCatalogId:Number(item.exam_catalog_id),quantity:Number(item.amount)||1})),payments:appliedPayments.value.map(item=>{const fields=paymentFields(item);return{typePaymentId:Number(item.typePaymentId),amount:round(item.amount),currency:selectedCurrency(item)?.isBase?"BASE":"LOCAL",fieldValues:fields.map(field=>({fieldId:Number(field.id),value:String(item.fieldValues[field.code]??""),bankId:field.fieldType==="bank"?Number(item.fieldValues[field.code])||undefined:undefined}))}})});successMessage.value="Ingreso cerrado correctamente.";emit("closed",result)}catch(error){loadError.value=patientAdmissionError(error,"No fue posible cerrar el ingreso.")}finally{saving.value=false}}onMounted(async()=>{try{[types.value,dollar.value]=await Promise.all([getTypePayments(),getCurrentDollarValue()]);addPayment()}catch(error){loadError.value=patientAdmissionError(error,"No fue posible cargar las formas de pago y la tasa.")}})</script>
<style scoped>.payment-step{display:grid;gap:var(--bio-nexus-space-3)}.payment-layout{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(300px,.7fr);gap:var(--bio-nexus-space-3);align-items:start}.payment-panel,.summary-panel{display:grid;align-content:start;gap:var(--bio-nexus-space-3);padding:var(--bio-nexus-space-4);border:1px solid var(--bio-nexus-color-border);border-radius:var(--bio-nexus-radius-md);background:var(--bio-nexus-color-surface)}.payment-row{display:grid;grid-template-columns:minmax(170px,1.4fr) minmax(130px,.8fr) minmax(110px,.7fr) repeat(2,minmax(120px,1fr)) auto;gap:8px;align-items:end;padding:10px;border:1px solid var(--bio-nexus-color-border);border-radius:8px;background:var(--bio-nexus-color-surface-soft)}.payment-row-actions{display:flex;gap:6px}.payment-icon-action{display:grid;place-items:center;width:32px;height:38px;border:1px solid transparent;border-radius:7px}.payment-remove-action{background:var(--bio-nexus-color-danger-soft);color:var(--bio-nexus-color-danger)}.payment-apply-action{background:var(--bio-nexus-color-info-soft);color:var(--bio-nexus-color-primary)}.payment-apply-action.applied{background:var(--bio-nexus-color-success-soft);color:var(--bio-nexus-color-success)}.money-input{text-align:right}.summary-panel{position:sticky;top:12px}.rate,.charge-total,.dual-status{display:grid;gap:6px;padding:10px;border:1px solid var(--bio-nexus-color-border);border-radius:8px}.rate,.charge-total{background:var(--bio-nexus-color-info-soft)}.payment-progress{height:8px;border-radius:999px;background:var(--bio-nexus-color-border);overflow:hidden}.payment-progress span{display:block;height:100%;background:var(--bio-nexus-color-primary)}.remaining-status{background:var(--bio-nexus-color-warning-soft)}.change-status{background:var(--bio-nexus-color-danger-soft)}.settled-status{background:var(--bio-nexus-color-success-soft)}.hint{margin:0;color:var(--bio-nexus-color-warning-strong);font-size:12px}.close-button{width:100%;justify-content:center}@media(max-width:1100px){.payment-layout{grid-template-columns:1fr}}@media(max-width:900px){.payment-row{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:620px){.payment-row{grid-template-columns:1fr}}</style>
